"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[92039],{78428:e=>{e.exports=JSON.parse('{"id":"2026-08-26-converse-2-0-api-documentation","date":"2026-08-26","products":["Converse"],"product":"Converse","channel":"","changeType":"Added","title":"Converse 2.0 API documentation, now at its own /converse section","excerpt":"Converse now has full API documentation, and its own top-level section on the developer portal \u2014 no longer nested under Connect.","hasArticle":true,"bodyHtml":"<p><strong>Converse</strong> now has full API documentation, and its own top-level section on the developer portal \u2014 no longer nested under Connect.</p>\\n<h2>Five new OpenAPI specs</h2>\\n<ul>\\n<li><strong>Conversation API</strong> \u2014 close a conversation, transfer it, list a contact&#39;s active conversations.</li>\\n<li><strong>MT Messaging API</strong> \u2014 send an outbound message, plain text or structured.</li>\\n<li><strong>Bot Response API</strong> \u2014 reply, transfer, close, and list, with structured replies (buttons, lists, CTAs, location requests, call permission requests, voice calls, and flows) on WhatsApp and Viber.</li>\\n<li><strong>Reporting API</strong> \u2014 conversations, chats, and agents.</li>\\n<li><strong>Setup API</strong> \u2014 channel accounts, agents, queues, dispositions, and autoresponder / business hours.</li>\\n</ul>\\n<p>Three new guides accompany the specs: an APIs overview, the Conversation Status Update Notification, and Bot integration.</p>\\n<h2>New URLs</h2>\\n<p>Converse&#39;s guides and API reference move from <code>/connect/docs/converse*</code> to <code>/converse</code>. Every previous URL \u2014 including the original <code>/connect/docs/moobidesk*</code> paths \u2014 keeps working.</p>\\n<table>\\n<thead>\\n<tr>\\n<th>Before</th>\\n<th>After</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td><code>/connect/docs/converse</code></td>\\n<td><code>/converse</code></td>\\n</tr>\\n<tr>\\n<td><code>/connect/docs/converse/getting-started</code></td>\\n<td><code>/converse/docs/getting-started</code></td>\\n</tr>\\n<tr>\\n<td><code>/connect/reference/converse-2-close-conversation</code></td>\\n<td><code>/converse/reference/close-conversation</code></td>\\n</tr>\\n</tbody></table>\\n<p>Converse is still reached from the CPaaS section on the <a href=\\"/connect\\">Connect</a> landing page.</p>\\n<h2>Read more</h2>\\n<ul>\\n<li><a href=\\"/converse\\">Converse</a></li>\\n<li><a href=\\"/converse/docs/api-overview\\">Converse APIs overview</a></li>\\n<li><a href=\\"/converse/reference\\">Converse API reference</a></li>\\n</ul>\\n"}')}}]);